contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target) public {
        require(_target.code.length == 0);

        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.sendMoney(_target, 0, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(address(c).balance == beforeBal && c.depositsCount() == beforeDeposits);
    }

    receive() external payable {}
}

