// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address _target) internal {
        vm.assume(_target.code.length == 0);
        uint beforeBal = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(_target, 0, "") { reverted = false; } catch { reverted = true; }
        assertTrue(address(c).balance == beforeBal && c.depositsCount() == beforeDeposits);
    }

    function testFuzz_run(address _target) public {
        vm.assume(_target.code.length == 0 && uint160(_target) > 0xffff && _target != address(this) && _target != address(c) && _target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _target != 0x000000000000000000636F6e736F6c652e6c6f67 && _target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_target);
    }

    receive() external payable {}
}
